/* Bonn Bash: deterministic opening and arcade selection screens. */
const arcadeImageCache=new Map();
function arcadeImage(path){if(!arcadeImageCache.has(path)){const image=new Image();image.src=path;arcadeImageCache.set(path,image)}return arcadeImageCache.get(path)}
function arcadeReady(image){return image?.complete&&image.naturalWidth>0}
class FrontOpening{
 constructor(game){this.game=game;this.time=0;this.hits=new Set();this.images=['bootGuard','bootWindup','bootPunch'].map(k=>arcadeImage(UI_ASSETS[k]));}
 get assetsReady(){return this.images.every(arcadeReady)}
 get ready(){return this.assetsReady&&this.time>=3.7}
 get needsRotation(){return this.game.mobile&&(globalThis.innerHeight||720)>(globalThis.innerWidth||1280)}
 update(dt){if(!this.assetsReady||!this.game.audio.unlocked)return;this.time+=dt;for(const t of [1,2])if(this.time>=t&&!this.hits.has(t)){this.hits.add(t);this.game.audio.play('punch')}}
 draw(c){c.fillStyle='#000';c.fillRect(0,0,W,H);if(!this.assetsReady){this.game.label('LOADING...',640,380,24);return}if(!this.game.audio.unlocked)this.game.label('PRESS ANY BUTTON',640,110,24,'#ffe397');const t=this.time,phase=t<1.55?t:t-1,index=t<2.4?(phase<.65?0:phase<1?1:2):0,im=this.images[index],pulse=index===2?1.16:1,w=650*pulse,h=w*im.naturalHeight/im.naturalWidth;c.imageSmoothingEnabled=false;c.drawImage(im,640-w/2,740-h,w,h);if([1,2].some(hit=>t>=hit&&t<hit+.06)){c.fillStyle='#fff9da';c.fillRect(0,0,W,H)}if(t>=2.4){c.fillStyle='#000b';c.fillRect(0,0,W,H);this.game.label(this.game.mobile?'ROTATE YOUR SCREEN':'GET READY!',640,330,this.game.mobile?48:72,'#ffe397');this.game.label(this.needsRotation?'QUERFORMAT / LANDSCAPE':'PRESS ANY BUTTON',640,420,24,'#fff1ce')}}
}

class ArcadeIntro{
 constructor(game){this.game=game;this.time=0;this.impact=false;this.hold=0;this.stage=new Stage(STAGES[0]);this.stage.ground=650;this.teacher=new Character(CHARACTERS.find(d=>d.id==='business'),0,this.stage);this.butter=new Character(CHARACTERS.find(d=>d.id==='herr-butter'),1,this.stage);this.teacher.facing=1;this.butter.facing=-1;this.logo=arcadeImage(UI_ASSETS.logo);this.background=arcadeImage(UI_ASSETS.opening);}
 get assetsReady(){return [this.logo,this.background,this.pose(this.teacher,'idle'),this.pose(this.teacher,'hit'),this.pose(this.butter,'idle'),this.pose(this.butter,'attack_medium',1)].every(arcadeReady)}
 get ready(){return this.time>=5.4&&this.assetsReady}
 skip(){this.time=5.4;this.impact=true;this.hold=0}
 update(dt){if(!this.assetsReady)return;if(this.hold>0){this.hold-=dt;return}this.time+=dt;this.teacher.anim.update(dt);this.butter.anim.update(dt);if(this.time>=2.42&&!this.impact){this.impact=true;this.hold=.10;this.game.audio.play('hit');this.game.audio.play('ko')}}
 static ease(t){return 1-Math.pow(1-clamp(t,0,1),3)}
 pose(f,key,index=0){const frames=f.anim.clips[key]?.frames||[];return frames[index%Math.max(1,frames.length)]}
 fighter(c,f,x,y,key,index=0,rotation=0){c.save();c.translate(Math.round(x),Math.round(y));c.scale(f.facing,1);c.rotate(rotation);const im=this.pose(f,key,index);if(arcadeReady(im)){const h=1050*f.bodyScale,w=h*im.naturalWidth/im.naturalHeight;c.drawImage(im,-w/2,-h,w,h)}else{c.scale(2.6,2.6);f.age=this.time;f.drawPlaceholder(c)}c.restore()}
 draw(c){const t=this.time;c.imageSmoothingEnabled=false;c.fillStyle='#030431';c.fillRect(0,0,W,H);if(arcadeReady(this.background))c.drawImage(this.background,0,0,W,H);if(!this.assetsReady){this.game.label('BONN BASH',640,320,48,'#ffdb69');this.game.label('LOADING...',640,385,24,'#e4e6ff');return}
 const dance=Math.round(Math.sin(t*11)*5);let bx=950-ArcadeIntro.ease((t-1.35)/.85)*135,px=330,py=1140+Math.round(Math.sin(t*11+1)*5),key='idle',frame=Math.floor(t*6)%2,rotation=0;
 if(t>=2.18&&t<2.85){key='attack_medium';frame=t<2.42?0:1}if(t>=2.85){key='idle';frame=Math.floor(t*5)%2}
 this.fighter(c,this.butter,bx,1140+dance,key,frame);
 if(t<4.05){if(t>=2.42){const p=clamp((t-2.42)/1.45,0,1);px=330-p*1120;py=1140-Math.sin(p*Math.PI)*260+p*p*260;rotation=-p*2.2;key='hit';frame=0}else{key='idle';frame=Math.floor(t*6)%2}this.fighter(c,this.teacher,px,py,key,frame,rotation)}
 if(t>=2.42&&t<2.72){const p=(t-2.42)/.3;c.save();c.translate(540,390);for(let i=0;i<12;i++){const a=i*Math.PI/6,r=22+p*95;c.fillStyle=i%2?'#fff8b5':'#ff7938';c.fillRect(Math.round(Math.cos(a)*r),Math.round(Math.sin(a)*r),12,7)}c.restore()}
 if(t<4.05){this.game.label('BONN · TANG SOO',640,50,24,'#ffe7a2');if(t<2.18)this.game.label('THE NEXT CHALLENGER…',640,700,16,'#fff1c6')}
 if(t>=4.05){c.fillStyle='#06042577';c.fillRect(0,0,W,H);const p=clamp((t-4.05)/1.1,0,1),ease=1+2.1*Math.pow(p-1,3)+1.1*Math.pow(p-1,2),y=-490+ease*535;if(arcadeReady(this.logo)){const width=850,height=width*this.logo.naturalHeight/this.logo.naturalWidth;c.drawImage(this.logo,(W-width)/2,Math.round(y),width,height)}else{this.game.label('BONN BASH',640,Math.round(y+200),80,'#ffcf42');this.game.label('TANG SOO EDITION',640,Math.round(y+265),24,'#fff0a6')}
 if(this.ready&&Math.floor((t-5.4)*2)%2===0)this.game.label('PRESS START',640,624,32,'#fff5bc');if(this.ready){this.game.label('BELIEBIGE TASTE · GAMEPAD · TOUCH',640,668,16,'#cddfff');this.game.label('© 2026 · ACESOFT',640,706,16,'#b8a5bf')}}
 }
}
class ArcadeScreens{
 static map(interactive=false){return `<div class="bonn-map ${interactive?'interactive-map':''}"><img class="bonn-map-art" src="${UI_ASSETS.map}" alt="Bonn-Karte mit Bahnhof, Rathaus, Halle, Frankenbad und Südstadt">${STAGES.map((s,i)=>`<button type="button" class="map-marker" tabindex="-1" data-map-stage="${i}" style="left:${s.mapPosition.x*100}%;top:${s.mapPosition.y*100}%" aria-label="${s.name} wählen" ${interactive?'':'disabled'}><span></span></button>`).join('')}${interactive?'<img class="map-traveller" id="map-traveller" alt="Gewählter Kämpfer auf dem Weg zur Stage">':''}</div>`}
 static select(g,player){g.state='select';g.selectPlayer=player;g.input.clear();g.previewSelection=[...g.selected];g.screen(`<div class="player-select-screen"><h2 class="arcade-heading">PLAYER SELECT</h2>${this.map(false)}<div class="selection-step">${player===0?'1P SELECT':g.localVersus?'2P SELECT':'SELECT OPPONENT'}</div>${[0,1].map(i=>`<aside class="large-player player-${i}"><div class="player-label">${i+1}P</div><div class="player-name" data-large-name="${i}">${CHARACTERS[g.selected[i]].displayName}</div><div class="portrait-window"><img data-large-portrait="${i}" src="${CHARACTERS[g.selected[i]].portraitPath}" alt="${CHARACTERS[g.selected[i]].displayName}"></div></aside>`).join('')}<div class="portrait-grid">${CHARACTERS.map((d,i)=>`<button class="portrait-cell ${g.selected[0]===i?'p1-picked':''} ${g.selected[1]===i?'p2-picked':''}" data-index="${i}" aria-label="${d.displayName} wählen"><img src="${d.portraitPath}" alt=""><span>${d.displayName}</span><b class="cursor-p1">1P</b><b class="cursor-p2">2P</b></button>`).join('')}</div><button class="arcade-back" data-action="menu">ZURÜCK</button><p class="selection-help">${player+1}P · KÄMPFER WÄHLEN</p></div>`);g.panel.classList.add('selection-ui');g.panel.querySelectorAll('[data-index]').forEach(b=>{const index=Number(b.dataset.index);b.onfocus=b.onpointerenter=()=>this.preview(g,player,index);b.onclick=()=>{g.audio.unlock();g.selected[player]=index;if(player===0)g.select(1);else g.selectStage()}});g.panel.querySelector('[data-index="'+g.selected[player]+'"]')?.focus()}
 static preview(g,player,index){g.previewSelection[player]=index;const d=CHARACTERS[index],image=g.panel.querySelector(`[data-large-portrait="${player}"]`),name=g.panel.querySelector(`[data-large-name="${player}"]`);if(image){image.src=d.portraitPath;image.alt=d.displayName}if(name)name.textContent=d.displayName;g.panel.querySelectorAll('[data-index]').forEach(b=>{const active=Number(b.dataset.index)===index;b.classList.toggle('active-cursor',active);b.classList.toggle(player===0?'p1-picked':'p2-picked',active)})}
 static stage(g){g.state='stage';g.stageTravel=null;g.input.clear();g.screen(`<div class="stage-select-screen"><h2 class="arcade-heading">STAGE SELECT</h2>${this.map(true)}<div class="location-strip">${STAGES.map((s,i)=>`<button class="location-chip" data-stage="${i}">${s.name}</button>`).join('')}</div><button class="arcade-back" data-action="menu">ZURÜCK</button><p class="stage-caption" id="stage-caption">BONN · ORT WÄHLEN</p></div>`);g.panel.classList.add('stage-ui');const traveller=g.panel.querySelector('#map-traveller');if(traveller){const idle=CHARACTERS[g.selected[0]].spritePaths.idle;traveller.src=Array.isArray(idle)?idle[0]:(idle.frames?.[0]||idle.base+'001.png');traveller.style.left=STAGES[0].mapPosition.x*100+'%';traveller.style.top=STAGES[0].mapPosition.y*100+'%'}const bind=(b,i)=>{b.onfocus=b.onpointerenter=()=>{g.panel.querySelectorAll('[data-map-stage]').forEach(n=>n.classList.toggle('active-marker',Number(n.dataset.mapStage)===i));const caption=g.panel.querySelector('#stage-caption');if(caption)caption.textContent=STAGES[i].name+' · BEREIT?'};b.onclick=()=>{if(g.stageTravel)return;g.audio.unlock();g.stageIndex=i;g.stageTravel={index:i,t:0,from:STAGES[0].mapPosition,to:STAGES[i].mapPosition};g.input.clear()}};g.panel.querySelectorAll('[data-stage]').forEach(b=>bind(b,Number(b.dataset.stage)));g.panel.querySelectorAll('[data-map-stage]').forEach(b=>bind(b,Number(b.dataset.mapStage)))}
 static updateTravel(g,dt){const a=g.stageTravel;if(!a)return;a.t+=dt;const p=ArcadeIntro.ease(a.t/.6),image=g.panel.querySelector('#map-traveller');if(image){image.style.left=(a.from.x+(a.to.x-a.from.x)*p)*100+'%';image.style.top=(a.from.y+(a.to.y-a.from.y)*p)*100+'%'}if(a.t>=.65){g.stageTravel=null;g.startMatch()}}
}

